using System.Collections.Generic;

var queue = new Queue<string>();

// Enqueue — O(1)
queue.Enqueue("A");
queue.Enqueue("B");
queue.Enqueue("C");

// Peek (front) — O(1)
Console.WriteLine(queue.Peek());  // A

// Dequeue — O(1)
Console.WriteLine(queue.Dequeue());  // A

Console.WriteLine(queue.Count);  // 2

from collections import deque

class Queue:
  def __init__(self):
      self.items = deque()

  def enqueue(self, item):
      self.items.append(item)

  def dequeue(self):
      if self.is_empty():
          raise IndexError("Queue is empty")
      return self.items.popleft()

  def front(self):
      if self.is_empty():
          raise IndexError("Queue is empty")
      return self.items[0]

  def is_empty(self):
      return len(self.items) == 0

  def size(self):
      return len(self.items)

# Usage
q = Queue()
q.enqueue("A")
q.enqueue("B")
q.enqueue("C")
print(q.front())    # A
print(q.dequeue())  # A
print(q.size())     # 2

package main

import "fmt"

func main() {
  var queue []string

  // Enqueue — O(1)
  queue = append(queue, "A", "B", "C")

  // Front — O(1)
  fmt.Println(queue[0])  // A

  // Dequeue — O(1)
  front := queue[0]
  queue = queue[1:]
  fmt.Println(front)  // A

  fmt.Println(len(queue))  // 2
}
